const CATS = 'IGNORE,FYI,JOB_ALERT,ACTION_NEEDED,JOB_REJECTION,RECRUITER_REPLY,JOB_CONFIRMATION'.split(',');
const q = $input.first().json.query || {};
const cat = String(q.cat || '').trim();
const row = String(q.row || '').trim().replace(/-/g, '');
const page = (icon, color, title, msg) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head><body style="margin:0;padding:48px 20px;background:#f9fafb;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;"><div style="max-width:420px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;padding:28px;text-align:center;"><div style="font-size:34px;line-height:1;">${icon}</div><div style="font-size:18px;font-weight:700;color:${color};margin-top:12px;">${title}</div><div style="font-size:14px;color:#4b5563;margin-top:10px;line-height:1.5;">${msg}</div></div></body></html>`;
if (!/^[0-9a-f]{32}$/i.test(row) || !CATS.includes(cat)) {
  return [{ json: { ok: false, status: 400, html: page('&#9888;&#65039;', '#b45309', 'Link not valid', 'That link had a missing or invalid row id or category, so nothing was changed. Fix the category in the Email Metrics Log in Notion by hand.') } }];
}
return [{ json: { ok: true, row, cat } }];

const v = $('Validate Request').first().json;
const upd = $('Update Metrics Row').first().json;
const page = (icon, color, title, msg) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head><body style="margin:0;padding:48px 20px;background:#f9fafb;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;"><div style="max-width:420px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;padding:28px;text-align:center;"><div style="font-size:34px;line-height:1;">${icon}</div><div style="font-size:18px;font-weight:700;color:${color};margin-top:12px;">${title}</div><div style="font-size:14px;color:#4b5563;margin-top:10px;line-height:1.5;">${msg}</div></div></body></html>`;
if (!upd || upd.error || !upd.id) {
  return [{ json: { status: 502, html: page('&#9888;&#65039;', '#b91c1c', 'Could not update', 'Notion did not accept the change (wrong row id, or Notion is unreachable). Nothing was confirmed. Fix it in the Email Metrics Log by hand.') } }];
}
const label = v.cat.replace(/_/g, ' ').toLowerCase();
return [{ json: { status: 200, html: page('&#9989;', '#15803d', 'Category corrected', 'Marked as <b>' + label + '</b>. Thanks &mdash; this becomes a trusted training label. You can close this tab.') } }];
